// \u7B7E\u540D\u7B97\u6CD5
function signature() {
	return t(Math.floor(Date.now() / 1000))
}

function t(e) {
	let str = e.toString()
	let r = [[], [], [], []]
	for (let i = 0; i < str.length; i++) {
		let e = he(str[i])
		r[0] += e.slice(2, 3)
		r[1] += e.slice(3, 4)
		r[2] += e.slice(4, 5)
		r[3] += e.slice(5)
	}
	let a = []
	for (let i = 0; i < r.length; i++) {
		let e = parseInt(r[i], 2).toString(16)
		if (e.length == 2) e = '0' + e
		if (e.length == 1) e = '00' + e
		if (e.length == 0) e = '000'
		a[i] = e
	}
	let n = CryptoJS.MD5(str).toString()
	return (
		n.slice(0, 3) +
		a[0] +
		n.slice(6, 11) +
		a[1] +
		n.slice(14, 19) +
		a[2] +
		n.slice(22, 27) +
		a[3] +
		n.slice(30)
	)
}

function he(e) {
	let t = []
	let r = e.split('')
	for (let i = 0; i < r.length; i++) {
		if (i != 0) t.push(' ')
		let code = r[i].charCodeAt().toString(2)
		t.push(code)
	}
	return t.join('')
}

